import spidev
import time
import signal
import sys

class LoadCellReader:
    def __init__(self):
        self.spi = spidev.SpiDev()
        if self.spi.open(0, 0) == 0:
            self.spi.max_speed_hz = 5000000
            print("SPI device opened successfully")
        else:
            raise OSError("Failed to open SPI device")

    def read_raw_data(self):
        cmd = [1, 0, 0x80]  # Three-byte command sequence
        try:
            response = self.spi.xfer2(cmd)
        except (OSError, IOError) as e:
            print(f"SPI error: {e}")
            self.close()
            sys.exit(1)
        return ((response[1] & 0x03) << 8) | response[2]

    def convert_to_weight(self, raw_value):
        # Assuming raw_value is in range 0-1023 and maps to 0-10 kg
        return raw_value * 0.1

    def close(self):
        self.spi.close()

def signal_handler(signal, frame):
    print("Clean shutdown initiated")
    loadcell.close()
    sys.exit(0)

signal.signal(signal.SIGTERM, signal_handler)

loadcell = LoadCellReader()

try:
    while True:
        raw_data = loadcell.read_raw_data()
        weight = loadcell.convert_to_weight(raw_data)
        print(f"Weight: {weight:.2f} kg")
        time.sleep(0.5)

except KeyboardInterrupt:
    print("\nProgram terminated by user")

except Exception as e:
    print(f"Fatal error: {e}")

finally:
    print("Closing SPI device and exiting")
    loadcell.close()

