logging.basicConfig(level=logging.INFO)

class ADS1015Controller:
    ADDRESS = 0x48
    BUSNUM = 1

    def __init__(self, address=ADDRESS, busnum=BUSNUM, debug=False):
        self.address = address
        self.busnum = busnum
        self.debug = debug
        try:
            self.i2c = i2c_device.I2C(board.SCL, board.SDA, frequency=400000)
            self.ads = ADS.ADS1015(self.i2c)
        except Exception as e:
            logging.error(f"Error initializing ADS1015: {e}")
            sys.exit(1)

    def read_adc_single_ended(self, channel=0, pga=6144, sps=250):
        try:
            return self.ads.read_adc(channel, gain=pga, sps=sps)
        except Exception as e:
            logging.error(f"Error reading ADC: {e}")
            return None

    def start_continuous_conversion(self, channel=0, pga=6144, sps=250):
        try:
            self.ads.config_start(channel, gain=pga, sps=sps)
        except Exception as e:
            logging.error(f"Error starting continuous conversion: {e}")

    def get_last_conversion_results(self):
        try:
            return self.ads.last_result
        except Exception as e:
            logging.error(f"Error getting last conversion results: {e}")
            return None

    def start_single_ended_comparator(self, channel=0, threshold_high=2047, threshold_low=0, pga=6144, sps=250, active_low=True, traditional_mode=True, latching=False, num_readings=1):
        try:
            self.ads.config_single_ended(channel, gain=pga, sps=sps, cmp_high=threshold_high, cmp_low=threshold_low, cmp_active_low=active_low, cmp_mode=traditional_mode, cmp_latch=latching, cmp_samples=num_readings)
        except Exception as e:
            logging.error(f"Error starting single-ended comparator: {e}")

    def cleanup(self):
        self.ads.close()
        self.i2c.close()

def signal_handler(signal, frame):
    print('You pressed Ctrl+C!')
    controller.cleanup()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)

controller = ADS1015Controller()

# Example usage
controller.start_continuous_conversion(channel=0)
time.sleep(1)
print(f"Last conversion result: {controller.get_last_conversion_results()}")

controller.start_single_ended_comparator(channel=0, threshold_high=2047, threshold_low=0, pga=6144, sps=250, active_low=True, traditional_mode=True, latching=False, num_readings=1)
time.sleep(1)
print(f"Single-ended comparator status: {controller.ads.comparator_result}")

