import spidev
import time
import board
import adafruit_mcp3008
import digitalio
import threading
import logging

logging.basicConfig(level=logging.INFO)

class SmartGardenController:
    def __init__(self):
        self.spi = spidev.SpiDev()
        self.mcp = adafruit_mcp3008.MCP3008(spi=self.spi)
        self.pump_gpio = digitalio.DigitalInOut(board.GPIO18)
        self.pump_gpio.direction = digitalio.Direction.OUTPUT
        self.pump_gpio.value = False

        if not self.mcp.is_ready():
            raise RuntimeError("MCP3008 not detected")
        if not self.pump_gpio.value:
            raise RuntimeError("Failed to set GPIO18 as output")

    def read_moisture(self):
        try:
            adc_data = self.mcp.read_adc(0)
            return adc_data
        except Exception as e:
            logging.error(f"Error reading moisture: {e}")
            return None

    def run_pump(self, seconds):
        self.pump_gpio.value = True
        time.sleep(seconds)
        self.pump_gpio.value = False

    def irrigation_cycle(self):
        moisture_raw = self.read_moisture()
        if moisture_raw is not None and moisture_raw > 450:
            self.run_pump(2)
            return True
        return False

    def close(self):
        self.mcp.close()
        self.pump_gpio.value = False

def schedule_cycles(controller, cycle_count, interval_seconds):
    for _ in range(cycle_count):
        controller.irrigation_cycle()
        time.sleep(interval_seconds)

if __name__ == "__main__":
    try:
        controller = SmartGardenController()
        schedule_cycles(controller, 10, 3)
    except KeyboardInterrupt:
        logging.info("Program interrupted by user")
    finally:
        controller.close()

