import time
import logging
from gpiozero import AnalogIn
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15 import ads1115
import sys
import signal

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class Oscilloscope:
    def __init__(self, bus=1):
        self.bus = bus
        self.ads = None
        self.ch0 = None
        self.ch1 = None
        self.running = True

    def initialize(self):
        try:
            self.ads = ads1115.ADS1115(i2c=i2c.I2C(bus=self.bus))
            self.ch0 = AnalogIn(self.ads.P0)
            self.ch1 = AnalogIn(self.ads.P1)
            logging.info("ADS1115 initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize ADS1115: {e}")
            raise

    def run(self):
        self.initialize()
        try:
            logging.info("Oscilloscope started.")
            while self.running:
                timestamp = time.monotonic()
                try:
                    ch0_v = self.ch0.value
                    ch1_v = self.ch1.value
                    print(f"{timestamp},{ch0_v},{ch1_v}")
                except Exception as e:
                    logging.error(f"Failed to read from channels: {e}")
                time.sleep(0.1)  # Sample at roughly 10 Hz
        except KeyboardInterrupt:
            logging.info("Oscilloscope stopped.")
        except Exception as e:
            logging.error(f"Unexpected error: {e}")

    def close(self):
        try:
            if self.ch0:
                self.ch0.close()
            if self.ch1:
                self.ch1.close()
            if self.ads:
                self.ads.close()
            logging.info("ADS1115 reference released.")
        except Exception as e:
            logging.error(f"Failed to release ADS1115 resources: {e}")

def signal_handler(signal, frame):
    logging.info("Received signal, stopping oscilloscope.")
    global running
    running = False

if __name__ == "__main__":
    running = True
    oscilloscope = Oscilloscope()

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        oscilloscope.run()
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        oscilloscope.close()
        sys.exit(0)

