import argparse
import time
import threading
import spidev
import board
import adafruit_mcp3008
import logging
from queue import Queue
from gpiozero import DigitalInputDevice, DeviceStoppedException

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.stop_event = threading.Event()

        if self.sensor_type == "digital":
            self.gpio = DigitalInputDevice(self.gpio_pins)
        elif self.sensor_type == "analog":
            self.mcp = adafruit_mcp3008.MCP3008(spi=spidev.SpiDev())
            self.mcp.spi_open(0, self.spi_speed)

        if self.sensor_type == "digital":
            self.gpio.when_activated = self.on_digital_event
        elif self.sensor_type == "analog":
            self.mcp.add_channel(self.channels)
            self.mcp.start_task_periodic(self.sample_rate, self.read_analog)

    def run(self):
        while not self.stop_event.is_set():
            try:
                if self.sensor_type == "digital":
                    self.gpio.wait()
                elif self.sensor_type == "analog":
                    self.mcp.update_task()
                if self.stop_event.is_set():
                    break
            except DeviceStoppedException:
                pass
            time.sleep(1 / self.sample_rate)

    def stop(self):
        self.stop_event.set()
        if self.sensor_type == "analog":
            self.mcp.close()

    def on_digital_event(self, channel):
        if self.log_queue:
            self.log_queue.put(f"Digital sensor {self.sensor_id} detected event on channel {channel}")

    def read_analog(self):
        adc_data = self.mcp.read_adc(self.channels)
        if adc_data is not None:
            if self.log_queue:
                self.log_queue.put(f"Analog sensor {self.sensor_id} detected event: {adc_data}")

def main(args):
    logging.basicConfig(filename=args.log_file, level=logging.INFO)

    sensors = []
    for sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels in zip(
        args.sensor_ids, args.sensor_type, args.threshold, args.sample_rate, args.gpio_pins, args.channels
    ):
        try:
            if sensor_type == "digital":
                gpio_pins = [int(pin.strip(), 16) for pin in gpio_pins.split(",")]
            else:
                gpio_pins = None

            sensor = SoundSensor(
                sensor_id, sensor_type, int(threshold), int(sample_rate), gpio_pins, int(channels), args.spi_speed
            )
            sensor_thread = threading.Thread(target=sensor.run)
            sensor_thread.start()
            sensors.append(sensor)

        except Exception as e:
            logging.error(f"Error initializing sensor {sensor_id}: {e}")

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        for sensor in sensors:
            sensor.stop()
        for sensor in sensors:
            sensor.join()

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Sound Sensor with Raspberry Pi")
    parser.add_argument("--sensor_type", choices=["digital", "analog"], required=True, nargs="+", help="Type of sensor (digital or analog)")
    parser.add_argument("--threshold", nargs="+", type=float, help="Threshold value for analog sensors")
    parser.add_argument("--sample_rate", nargs="+", type=int, help="Sample rate in Hz")
    parser.add_argument("--log_file", help="Log file for events")
    parser.add_argument("--gpio_pins", help="Comma-separated list of GPIO pins for digital sensors")
    parser.add_argument("--channels", type=int, help="Channel number for analog sensors")
    parser.add_argument("--spi_speed", type=int, default=1000000, help="SPI speed in Hz (default: 1000000)")
    parser.add_argument("--sensor_ids", nargs="+", help="Unique identifier for each sensor")

    args = parser.parse_args()

    main(args)

