import adafruit_bus_device
import logging
from datetime import datetime
import sys

try:
    i2c = adafruit_bus_device.I2C(board.SCL, board.SDA)
    max30100 = adafruit_max30102.MAX30102(i2c)
except Exception as e:
    print(f"Error initializing I2C or MAX30102: {e}")
    sys.exit(1)

def format_value(value):
    try:
        return int(value)
    except (ValueError, TypeError):
        return None

def log_heart_rate(heart_rate):
    timestamp = datetime.now().isoformat()
    with open("heart_rate_log.txt", "a") as log_file:
        log_file.write(f"{timestamp},{heart_rate}\n")
    print(f"Heart Rate: {heart_rate} bpm")

def main_loop():
    peak_window = []
    while True:
        try:
            ir_adc = format_value(max30100.ir_adc)
            red_adc = format_value(max30100.red_adc)

