import time
import logging
import sqlite3
import configparser
from gpiozero import I2C
from adafruit_bmp280 import BMP280
from adafruit_bme280 import BME280
from adafruit_ms8607 import MS8607
from paho.mqtt import client as mqtt_client

# Setup logging
logging.basicConfig(filename='error.log', level=logging.ERROR)

# I2C bus setup
i2c = I2C(scl=2, sda=3)

# Database setup
conn = None
try:
    conn = sqlite3.connect('wildlife_data.db')
    cursor = conn.cursor()
    cursor.execute('''CREATE TABLE IF NOT EXISTS sensor_data
                     (timestamp TEXT, sensor_type TEXT, sensor_id TEXT, pressure_pa INTEGER, temperature_c REAL, humidity_percent REAL)''')
except sqlite3.Error as e:
    logging.error(f"Database error: {e}")

# Read config
config = configparser.ConfigParser()
if not os.path.exists('config.txt'):
    logging.warning("No config file found, using defaults.")
    config['Sensor1'] = {'Type': 'BMP280', 'Address': 0x77, 'ID': 1, 'Sampling_Interval': 60}
    config['Sensor2'] = {'Type': 'BME280', 'Address': 0x76, 'ID': 2, 'Sampling_Interval': 60}
    config['Sensor3'] = {'Type': 'MS8607', 'Address': 0x1D, 'ID': 3, 'Sampling_Interval': 60}
else:
    config.read('config.txt')

# Sensor initialization
sensors = []
for sensor_name, settings in config.items():
    try:
        if settings['Type'] == 'BMP280':
            sensor = BMP280(i2c, address=int(settings['Address'], 16))
        elif settings['Type'] == 'BME280':
            sensor = BME280(i2c, address=int(settings['Address'], 16))
        elif settings['Type'] == 'MS8607':
            sensor = MS8607(i2c, address=int(settings['Address'], 16))
        else:
            logging.error(f"Unknown sensor type: {settings['Type']}")
            continue
        sensors.append((sensor_name, sensor, int(settings['Sampling_Interval'])))
    except Exception as e:
        logging.error(f"Failed to initialize {settings['Type']} sensor: {e}")

if not sensors:
    sys.exit(0)

def store_data(sensor_type, sensor_id, pressure, temperature, humidity):
    try:
        timestamp = time.strftime('%Y-%m-%dT%H:%M:%SZ')
        cursor.execute("INSERT INTO sensor_data VALUES (?, ?, ?, ?, ?, ?)",
                       (timestamp, sensor_type, sensor_id, pressure, temperature, humidity))
        conn.commit()
    except sqlite3.Error as e:
        logging.error(f"Database insert error: {e}")

def validate_data(pressure, temperature, humidity):
    if not (70000 <= pressure <= 110000):
        logging.warning(f"Invalid pressure: {pressure} Pa")
        return False
    if not (-20 <= temperature <= 50):
        logging.warning(f"Invalid temperature: {temperature} °C")
        return False
    if humidity is not None and (not (0 <= humidity <= 100)):
        logging.warning(f"Invalid humidity: {humidity}%")
        return False
    return True

def read_sensors():
    for sensor_name, sensor, interval in sensors:
        try:
            if sensor.type == 'BMP280' or sensor.type == 'BME280':
                pressure, temperature = sensor.read_temperature_pressure()
                humidity = None
            elif sensor.type == 'MS8607':
                pressure, temperature, humidity = sensor.read_orientation()
            else:
                logging.error(f"Unknown sensor type: {sensor.type}")
                continue

            if validate_data(pressure, temperature, humidity):
                store_data(sensor_name, sensor.id, pressure, temperature, humidity)
        except Exception as e:
            logging.error(f"Failed to read from {sensor_name}: {e}")
        time.sleep(interval)

try:
    while True:
        read_sensors()
        time.sleep(1)
except KeyboardInterrupt:
    logging.info("Program terminated by user.")
finally:
    if conn:
        conn.close()

