import random
import paho.mqtt.client as mqtt
from gpiozero import Buzzer
import signal
import sys

buzzer = Buzzer(17)

def detect_human(thermal_data):
    return any(temp > 30 for temp in thermal_data)

def trigger_alert(buzzer):
    buzzer.on()
    time.sleep(1)
    buzzer.off()

def i2c_error_handler(func):
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except IOError:
            print("I2C bus error or sensor missing. Using simulated data.")
            return [[random.uniform(20, 45) for _ in range(8)] for _ in range(8)]
    return wrapper

@i2c_error_handler
def read_thermal_data():
    i2c = board.I2C()
    sensor = adafruit_amg8833.AMG8833(i2c)
    return sensor.read_data()

def mqtt_callback(client, userdata, message):
    print(f"Received MQTT message: {message.topic} {str(message.payload)}")

def setup_mqtt():
    client = mqtt.Client()
    client.on_message = mqtt_callback
    client.connect("mqtt_broker_address", 1883, 60)
    client.subscribe("temperature_topic")
    client.loop_forever()

def signal_handler(signal, frame):
    print("\nCleaning up resources...")
    buzzer.close()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

if __name__ == "__main__":
    try:
        i2c_bus = read_thermal_data()
        print("Starting thermal camera monitoring...")
        while True:
            if detect_human(i2c_bus):
                print("Human detected! Triggering alert.")
                trigger_alert(buzzer)
                mqtt_client_thread = threading.Thread(target=setup_mqtt)
                mqtt_client_thread.start()
            print(f"Thermal data: {i2c_bus}")
            time.sleep(0.1)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        buzzer.close()

