import serial
import struct
import math

# Initialize serial connection to GPS module
ser = serial.Serial('/dev/serial0', 9600, timeout=1)

def degrees_decimal_to_dms(degrees_decimal):
    if not isinstance(degrees_decimal, (int, float)):
        raise ValueError("Input must be a real number")

    sign = -1 if degrees_decimal < 0 else 1
    degrees_decimal *= sign

    integer_part, fractional_part = math.modf(abs(degrees_decimal))
    minutes, seconds = divmod(fractional_part * 60 * 100, 1)

    return (int(integer_part), int(minutes), int(seconds * sign))

def number_to_exif_rational(number):
    if not isinstance(number, (int, float)):
        raise ValueError("Input must be a real number")

    whole, fraction = math.modf(number)
    if fraction != 0:
        gdc = math.gcd(int(whole), int(fraction * 1000))
        whole //= gdc
        fraction //= gdc

        if not isinstance(whole, int) or not isinstance(fraction, int):
            raise TypeError("Numerator and denominator must be integers")

        return (whole, 1000)
    else:
        return (int(whole), 1)

try:
    while True:
        if ser.in_waiting > 0:
            line = ser.readline().decode('utf-8').strip()
            if '$GPRMC' in line:
                parts = line.split(',')
                lat_decimal = float(parts[2])
                lon_decimal = float(parts[4])

                lat_dms = degrees_decimal_to_dms(lat_decimal)
                lon_dms = degrees_decimal_to_dms(lon_decimal)

                print(f"Latitude: {lat_dms[0]}° {abs(lat_dms[1])}′ {abs(lat_dms[2])}\"N")
                print(f"Longitude: {lon_dms[0]}° {abs(lon_dms[1])}′ {abs(lon_dms[2])}\"E")

                lat_rational = number_to_exif_rational(lat_decimal)
                lon_rational = number_to_exif_rational(lon_decimal)

                print(f"EXIF Latitude: {lat_rational[0]}/{lat_rational[1]}")
                print(f"EXIF Longitude: {lon_rational[0]}/{lon_rational[1]}")

except ValueError as ve:
    print(f"Value Error: {ve}")
except TypeError as te:
    print(f"Type Error: {te}")
finally:
    ser.close()

