import os
import time
import signal
import board
import adafruit_dht
import busio
import digitalio
import audiocore
import audioioport
import picamera
import paho.mqtt.client as mqtt
from gpiozero import LED
from adafruit_dht.dht_sensor import DHTSensor
from adafruit_dht.dht_types import DHT11

# Initialize GPIO
try:
    gpio = board.GPIO()
except Exception as e:
    print(f"GPIO initialization failed: {e}")
    gpio = SimulatedGPIO()

# Initialize DHT11 sensor
try:
    i2c = busio.I2C(board.SCL, board.SDA)
    dht_sensor = DHTSensor(DHT11, gpio.pin_factory(4, digitalio.DigitalInOut(4)))
except Exception as e:
    print(f"DHT11 sensor initialization failed: {e}")
    dht_sensor = SimulatedDHTSensor()

# Initialize light relay
light_relay = LED(gpio.pin_factory(17, digitalio.DigitalInOut(17)))

# Initialize camera
camera = picamera.PiCamera()

# Initialize audio
audio = audiocore.Audio(busio.I2S(board.SCK, board.MISO, board.MOSI, board.WD_CTS, board.WD_RTS))
audio_port = audioioport.AudioIO(audio)

# MQTT client
client = mqtt.Client()
client.connect_async("mqtt_broker_address")

def read_temperature():
    try:
        data = dht_sensor.read()
        if data.is_valid:
            return data.temperature
        else:
            print("Temperature sensor error, using simulated temperature.")
            return round(random.uniform(15, 35), 2)
    except Exception as e:
        print(f"Temperature sensor library error: {e}")
        return round(random.uniform(15, 35), 2)

def take_picture():
    try:
        camera.capture('greenhouse_{timestamp}.jpg', use_video_port=True)
    except Exception as e:
        print(f"Camera capture failed: {e}")

def listen_for_wake_word():
    with audio_port.record() as audio_recorder:
        audio_recorder.start(timeout=5)
        for chunk in audio_recorder.read():
            if "Greenhouse" in chunk.decode():
                return True
    return False

def on_signal(signum, frame):
    gpio.cleanup()
    if camera:
        camera.close()
    os._exit(0)

signal.signal(signal.SIGINT, on_signal)
signal.signal(signal.SIGTERM, on_signal)

while True:
    if listen_for_wake_word():
        command = input("Enter command: ").lower()
        if "turn on the lights" in command:
            light_relay.on()
        elif "turn off the lights" in command:
            light_relay.off()
        elif "what is the temperature" in command:
            print(f"Temperature: {read_temperature()} °C")
        elif "take a picture" in command:
            take_picture()
        else:
            print("Unknown command.")

    time.sleep(1)

