    def __init__(self, camera, *args, **kwargs):
        super().__init__(camera, *args, **kwargs)
        self.buffer = io.BytesIO()

    def write(self, data):
        self.buffer.write(data)
        if self.frame_complete:
            try:
                self.sink.write(self.buffer.getvalue())
                self.buffer.seek(0)
                self.buffer.truncate()
            except IOError as e:
