    try:
        bus = smbus2.SMBus(I2C_BUS)
        print(f"I2C bus {I2C_BUS} initialized successfully.")
        return bus
    except Exception as e:
        print(f"Error initializing I2C bus {I2C_BUS}: {e}")
        return None

def main():
    i2c_bus = initialize_i2c()
    if i2c_bus:
        try:
            while True:
                read_temperature()
                time.sleep(2)
        except KeyboardInterrupt:
            print("\nExiting...")
        finally:
            if i2c_bus:
                i2c_bus.close()

if __name__ == "__main__":
    main()

