import time
import logging
import board
import adafruit_dht
from adafruit_dht.dht_device import DHTDevice
from adafruit_dht.dht_types import DHT20
import busio

logging.basicConfig(level=logging.INFO)
log = logging.getLogger()

class DHT20Sensor:
    def __init__(self, sda=board.D4, scl=board.D5):
        self.i2c = busio.I2C(board.SCL, board.SDA)
        self.device = None
        self.retries = 5
        self.retry_delay = 2
        self.timeout = 0.1
        self.status_timeout = 0.5
        self.status_mask = 0x80
        self.crc_poly = 0x07
        self.crc_init = 0xFF
        self.crc_shift = 8
        self.register_status = 0x00
        self.register_data = 0x01
        self.attempts = 0
        self.sda = sda
        self.scl = scl

    def __del__(self):
        self.close()

    def close(self):
        if self.device:
            self.device.close()
        self.i2c.close()

    def initialize(self):
        try:
            self.device = DHTDevice(self.i2c, DHT20)
            self.device.address = 0x54  # DHT20 I2C address
            self.device.i2c.writeto_mem(self.device.address, self.register_power_up, 1)
            time.sleep(self.status_timeout)
            self.check_status()
        except Exception as e:
            log.error(f"Failed to initialize DHT20 sensor: {e}")
            return False
        return True

    def check_status(self):
        start_time = time.time()
        while (self.device.read_byte_data(self.register_status) & self.status_mask) == self.status_mask:
            if time.time() - start_time > self.timeout:
                log.warning("Timeout waiting for DHT20 status to clear.")
                return False
            time.sleep(0.01)
        return True

    def read_data(self):
        if not self.initialize():
            return False

        while self.attempts < self.retries:
            try:
                raw_humidity = (self.device.read_i2c_block_data(self.register_data, 3, 3) << 8) | self.device.read_i2c_block_data(self.register_data, 0, 3)
                raw_temperature = (self.device.read_i2c_block_data(self.register_data, 3, 3) << 8) | self.device.read_i2c_block_data(self.register_data, 0, 3)
                crc = self.device.read_byte_data(self.register_data, 6)

                crc_calculated = self.calculate_crc(raw_humidity | raw_temperature)
                if crc != crc_calculated:
                    log.warning("CRC mismatch, data rejected.")
                    return (None, None, True)

                temperature = self.convert_to_celsius(raw_temperature)
                humidity = self.convert_to_relative_humidity(raw_humidity)
                return (temperature, humidity, False)

            except Exception as e:
                log.error(f"Error reading DHT20 data: {e}")
                self.attempts += 1
                if self.attempts >= self.retries:
                    return (None, None, True)
                time.sleep(self.retry_delay)

    def calculate_crc(self, data):
        crc = self.crc_init
        for byte in data:
            crc ^= byte << self.crc_shift
            for _ in range(8):
                if crc & 0x8000:
                    crc = (crc << 1) ^ self.crc_poly
                else:
                    crc <<= 1
        return crc & 0xFF

    def convert_to_celsius(self, raw_temperature):
        return (raw_temperature / 4195.0) - 46.0

    def convert_to_relative_humidity(self, raw_humidity):
        return (raw_humidity / 1048576.0) * 100.0

# Example usage:
sensor = DHT20Sensor()
while True:
    result = sensor.read_data()
    if result[2]:
        log.error("Failed to read data after all retries.")
    else:
        temperature, humidity, crc_error = result
        print(f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%")

