import paho.mqtt.client as mqtt

class WeatherSensor:
    def __init__(self, port='/dev/ttyUSB0', baudrate=9600):
        self.ser = serial.Serial(port, baudrate, timeout=1)
        self.ser.parity = serial.PARITY_NONE
        self.ser.stopbits = serial.STOPBITS_ONE
        self.ser.bytesize = serial.EIGHTBITS
        self.mqtt_broker = "your_mqtt_broker"
        self.mqtt_topic = "weather_data"
        self.mqtt_client = mqtt.Client()
        self.mqtt_client.connect(self.mqtt_broker)

    def read_sensor(self):
        try:
            while True:
                line = self.ser.readline().decode('utf-8').strip()
                if not line:
                    continue
                try:
                    temp, humidity, pressure = map(float, line.split(','))
                    if -40 <= temp <= 85 and 0 <= humidity <= 100 and 800 <= pressure <= 1200:
                        timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                        self.mqtt_client.publish(self.mqtt_topic, f"{timestamp},{temp},{humidity},{pressure}")
                        print(f"{timestamp},{temp},{humidity},{pressure}")
                    else:
                        print(f"Warning: Invalid reading - {line}")
                except ValueError:
                    print(f"Warning: Malformed line - {line}")
        except serial.SerialException as e:
            print(f"Error reading from serial port: {e}")

    def clean_exit(self, signum, frame):
        self.ser.close()
        self.mqtt_client.disconnect()

    def run(self):
        signal.signal(signal.SIGINT, lambda x, y: self.clean_exit(x, y))
        signal.signal(signal.SIGTERM, lambda x, y: self.clean_exit(x, y))

        self.read_sensor()

if __name__ == "__main__":
