import time
import random
import csv
import board
import adafruit_bme280
from adafruit_bme280.exceptions import OSError
import os

I2C_BUS = 1

def simulate_sensor():
    return random.uniform(20.0, 26.0), random.uniform(35.0, 55.0)

def calculate_comfort(temp, hum):
    if 21.0 <= temp <= 24.0 and hum <= 50:
        return "COMFORTABLE"
    elif temp > 24.0 or hum > 55:
        return "TOO_WARM"
    else:
        return "ACCEPTABLE"

def log_to_csv(data):
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
    with open("store_environment.csv", "a", newline='') as csvfile:
        fieldnames = ["timestamp", "temperature", "humidity", "comfort"]
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames)

        if csvfile.tell() == 0:
            writer.writeheader()

        writer.writerow({
            "timestamp": timestamp,
            "temperature": data[0],
            "humidity": data[1],
            "comfort": data[2]
        })

try:
    i2c = board.I2C(bus=I2C_BUS, sda=board.D2, scl=board.D3)
    sensor = adafruit_bme280.Adafruit_BME280_I2C(i2c)

    for _ in range(10):
        try:
            (temp, hum) = sensor.temperature, sensor.humidity
        except OSError:
            temp, hum = simulate_sensor()

        comfort = calculate_comfort(temp, hum)
        log_to_csv((temp, hum, comfort))
        time.sleep(2)

except KeyboardInterrupt:
    print("\nExiting...")

finally:
    sensor.close()
    os.sync()  # Ensure all data is written to disk
    print("I2C bus closed, CSV file flushed.")

