import os
import time
import board
import adafruit_pca9685
import paho.mqtt.client as mqtt
import re

class FanControl:
    def __init__(self):
        self.pwm = adafruit_pca9685.PCA9685(busio.I2C(board.SCL, board.SDA), address=0x60)
        self.pwm.frequency = 100
        self.pwm.duty_cycle = 0
        self.pwm.channels[4].frequency = 100
        self.pwm.channels[4].duty_cycle = 0

        self.temp_source = os.getenv('VCGENCMD', None)
        self.temp_file = '/sys/class/thermal/thermal_zone0/temp'

        if self.temp_source:
            self.read_temp = self.read_temp_vcgencmd
        else:
            self.read_temp = self.read_temp_file

    def read_temp_vcgencmd(self):
        try:
            result = os.popen('vcgencmd measure_temp').read().strip()
            return float(result.split('=')[1])
        except Exception as e:
            print(f"Error reading temperature using vcgencmd: {e}")
            return None

    def read_temp_file(self):
        try:
            with open(self.temp_file, 'r') as f:
                temp_raw = float(f.read().strip())
                temp_celsius = temp_raw / 1000.0
                return temp_celsius
        except Exception as e:
            print(f"Error reading temperature from file: {e}")
            return None

    def set_fan_speed(self, temp):
        if temp is None:
            return

        min_temp, max_temp, min_speed, max_speed = 25, 60, 0, 100
        if min_temp <= temp <= max_temp:
            duty_cycle = int((temp - min_temp) * (max_speed - min_speed) / (max_temp - min_temp)) + min_speed
            self.pwm.channels[4].duty_cycle = duty_cycle
        else:
            self.pwm.channels[4].duty_cycle = min(max(0, duty_cycle), 100)

    def log_temp_and_speed(self, temp, speed):
        print(f"Temperature: {temp}°C, Fan Speed: {speed}")

    def run(self):
        try:
            while True:
                temp = self.read_temp()
                self.set_fan_speed(temp)
                self.log_temp_and_speed(temp, self.pwm.channels[4].duty_cycle)
                time.sleep(5)

        except KeyboardInterrupt:
            print("\nExiting...")
        except Exception as e:
            print(f"An error occurred: {e}")
        finally:
            self.pwm.deinit()

def on_connect(client, userdata, flags, rc):
    print(f"Connected with result code {rc}")

def on_log(client, userdata, level, buf):
    print(f"{level}: {buf.decode()}")

def main():
    fan_control = FanControl()
    mqtt_client = mqtt.Client()
    mqtt_client.on_connect = on_connect
    mqtt_client.on_log = on_log

    mqtt_client.connect("mqtt_broker_address", 1883, 60)
    mqtt_client.subscribe("fan_control/topic")

    try:
        fan_control.run()
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        mqtt_client.disconnect()

if __name__ == "__main__":
    main()

