LED_PIN = 17
led = None

class RequestHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        global led

        if self.path == '/':
            self.send_response(200)
            self.send_header('Content', 'text/html')
            self.end_headers()
            self.wfile.write(b'<html><body><a href="/light_on">Turn LED On</a> | <a href="/light_off">Turn LED Off</a></body></html>')
        elif self.path == '/light_on':
            self.send_response(200)
            self.send_header('Content', 'text/html')
            self.end_headers()
            if led:
                led.on()
                self.wfile.write(b'<html><body>LED is ON. <a href="/light_off">Turn LED Off</a></body></html>')
            else:
                self.wfile.write(b'<html><body>Error: LED not initialized</body></html>')
        elif self.path == '/light_off':
            self.send_response(200)
            self.send_header('Content', 'text/html')
            self.end_headers()
            if led:
                led.off()
                self.wfile.write(b'<html><body>LED is OFF. <a href="/light_on">Turn LED On</a></body></html>')
            else:
                self.wfile.write(b'<html><body>Error: LED not initialized</body></html>')
        else:
            self.send_response(404)
            self.end_headers()

def signal_handler(signal, frame):
    global led
    if led:
        led.off()
    exit(0)

def setup_led():
    global led
    try:
        led = LED(LED_PIN)
    except Exception as e:
        print(f"Error initializing LED: {e}")
        led = None

def main():
    setup_led()

    server_address = ('', 8080)
    httpd = HTTPServer(server_address, RequestHandler)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        print(f"Serving on port {server_address[1]}...")
        httpd.serve_forever()
    except Exception as e:
        print(f"Error in HTTP server: {e}")
    finally:
        if led:
            led.off()
            GPIO.cleanup()

if __name__ == '__main__':
    main()

import time
import signal
import sys
from datetime import datetime
from collections import deque
from gpiozero import MotionSensor
from gpiozero.pins.pigpio import PiGPIOFailedError

class PIROccupancyMonitor:
    def __init__(self, debounce_interval=2.0, sample_count=10):
        self.debounce_interval = debounce_interval
        self.sample_count = sample_count
        self.events = deque(maxlen=sample_count)
        self.motion_sensor = None
        self.initialized = False

    def initialize(self):
        try:
            self.motion_sensor = MotionSensor(17)
            self.motion_sensor.when_motion = self.on_motion
            self.initialized = True
        except PiGPIOFailedError:
            print("Failed to initialize GPIO. Exiting.")
            sys.exit(1)

    def on_motion(self, motion):
        current_time = datetime.now().isoformat()
        self.events.append(current_time)
        print(f"Motion detected at: {current_time}")

    def run(self):
        if not self.initialized:
            self.initialize()

        try:
            while True:
                time.sleep(0.5)
        except KeyboardInterrupt:
            print("\nExiting gracefully...")
            sys.exit(0)
        except Exception as e:
            print(f"An error occurred: {e}")
            sys.exit(1)
        finally:
            if self.motion_sensor:
                self.motion_sensor.close()

    def get_stats(self):
        return {
            "total_events": len(self.events),
        }

    def print_summary(self):
        stats = self.get_stats()
        print(f"\nOccupancy Summary:\nTotal events: {stats['total_events']}")

def main():
    monitor = PIROccupancyMonitor()
    monitor.run()
    monitor.print_summary()

if __name__ == "__main__":
    main()

