class OutputPin(GPIOZeroOutputDevice):
    def __init__(self, pin_number: int, initial_value: int):
        if not (0 <= pin_number <= 31):
            raise ValueError("Pin number must be between 0 and 31")
        if initial_value not in [0, 1]:
            raise ValueError("Initial value must be either 0 or 1")

        super().__init__(pin_number, initial_value)
        self.pi = pigpio.pi()
        if not self.pi.connected:
            raise ConnectionError("Failed to connect to pigpio daemon")

    def set_value(self, value: int):
        if value not in [0, 1]:
            raise ValueError("Value must be either 0 or 1")
        try:
            super().on() if value else super().off()
        except PiGPIOWarning:
            self.pi.stop()
            raise

    def shutdown(self):
        try:
            super().off()
        except PiGPIOWarning:
            pass
        self.pi.stop()

