            if line.startswith('start_file='):
                board_rev = line.split('=')[1].strip()
                if board_rev == '0001':
                    return 'Rev 1'
                elif board_rev == '0010':
                    return 'Rev 2'
    return 'Unknown'

def get_gpio_num():
    model = get_raspi_model()
    if model == 'Rev 1':
        return 17
    elif model == 'Rev 2':
        return 26
    else:
        return 0

def signal_handler(signal, frame):
    print("\nExiting...")
    gpio.cleanup()
    sys.exit(0)

