    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        pass

    for input_device in inputs:
        input_device.cancel_when_changed()

    gpio.cleanup()

except RuntimeError as e:
    print(f"Error: {e}")
    sys.exit(1)

