class LEDController:
    def __init__(self, pin):
        if not isinstance(pin, int) or pin < 0 or pin > 255:
            raise ValueError("Invalid pin number. Must be an integer between 0 and 255.")
        self.led = LED(pin)
        adafruit_blinka.pigpio.set_mode(self.led.pigpio, pin, PololuDriver)
        adafruit_blinka.pigpio.start()
