        self.led.on()

    def off(self):
        self.led.off()

    def blink(self, on_duration, off_duration):
        if on_duration < 0 or off_duration < 0:
            raise ValueError("Durations must be non-negative.")
        self.on_duration = on_duration
        self.off_duration = off_duration
        while True:
            self.on()
            time.sleep(self.on_duration)
            self.off()
            time.sleep(self.off_duration)

    def cleanup(self):
        adafruit_blinka.pigpio.stop()

