import time
import board
import busio
import adafruit_tcs34725
import os
from PIL import Image
from io import BytesIO
import paho.mqtt.client as mqtt

# I2C bus configuration
I2C_BUS = busio.I2C(board.SCL, board.SDA)

# MQTT configuration
MQTT_BROKER = "localhost"
MQTT_PORT = 1883
MQTT_TOPIC = "color_data"

def init_i2c():
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        return i2c
    except Exception as e:
        print(f"I2C bus initialization failed: {e}")
        return None

def tcs34725_read(i2c):
    try:
        sensor = adafruit_tcs34725.TCS34725(i2c)
        sensor.gain = 4
        sensor.integration_time = 50
        return sensor.rgb
    except Exception as e:
        print(f"Error reading from TCS34725: {e}")
        return (0, 0, 0, 0)

def get_dominant_color(image_path):
    try:
        img = Image.open(image_path)
        img = img.resize((100, 100))
        pixels = img.convert("RGB")
        pixel_counts = {"red": (0, 0, 0), "green": (0, 0, 0), "blue": (0, 0, 0)}

        for pixel in pixels.getdata():
            r, g, b = pixel
            pixel_counts[chr(65 + pixel_counts.index((r, g, b)))] = (
                pixel_counts[chr(65 + pixel_counts.index((r, g, b)))][0] + 1,
                pixel_counts[chr(65 + pixel_counts.index((r, g, b)))][1] + 1,
                pixel_counts[chr(65 + pixel_counts.index((r, g, b)))][2] + 1,
            )

        dominant_color = max(pixel_counts, key=lambda x: pixel_counts[x])
        return tuple(pixel_counts[dominant_color])

    except Exception as e:
        print(f"Error processing image: {e}")
        return (0, 0, 0)

def mqtt_publish(data):
    client = mqtt.Client()
    client.connect(MQTT_BROKER, MQTT_PORT)
    client.publish(MQTT_TOPIC, str(data))
    client.disconnect()

def main():
    i2c = init_i2c()
    if not i2c:
        return

    sensor_data = tcs34725_read(i2c)
    dominant_color = get_dominant_color("image.jpg")

    while True:
        print(f"Sensor Data: {sensor_data}, Dominant Color: {dominant_color}")
        mqtt_publish((sensor_data, dominant_color))
        time.sleep(1)

    except (KeyboardInterrupt, SIGTERM):
        i2c.deinit()
        print("Clean shutdown")

if __name__ == "__main__":
    main()

