import time
import random
import board
import adafruit_dht
import adafruit_gpio.pi as GPIO
import paho.mqtt.client as mqtt

# MQTT settings
MQTT_BROKER = "localhost"
MQTT_PORT = 1883
MQTT_TOPIC = "soil_moisture"

# GPIO setup
try:
    pump_pin = board.D4  # BCM pin 17
    GPIO.setup(pump_pin, GPIO.OUT)
except PermissionError:
    print("Permission denied. Check your GPIO pin access.")
except IOError:
    print("Hardware error. Check your GPIO pin connection.")

def simulate_moisture():
    return random.randint(0, 100)

def control_pump(moisture):
    if moisture < 30:
        GPIO.output(pump_pin, GPIO.HIGH)
        print(f"Pump ON: Moisture level is below 30%")
    else:
        GPIO.output(pump_pin, GPIO.LOW)
        print(f"Pump OFF: Moisture level is 30% or above")

def mqtt_callback(client, userdata, message):
    moisture = int(message.payload.decode())
    print(f"Received moisture level: {moisture}")
    control_pump(moisture)

def main():
    client = mqtt.Client()
    client.on_message = mqtt_callback
    client.connect(MQTT_BROKER, MQTT_PORT)
    client.subscribe(MQTT_TOPIC)
    client.loop_forever()

if __name__ == "__main__":
    for i in range(5):
        moisture = simulate_moisture()
        print(f"Iteration {i+1}: Moisture level = {moisture}%")
        control_pump(moisture)
        time.sleep(2)

    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"Error during cleanup: {e}")

    try:
        client.disconnect()
    except Exception as e:
        print(f"Error disconnecting MQTT client: {e}")

