        if not 0 <= duty_cycle <= 100:
            raise ValueError("Duty cycle must be between 0 and 100")
        self.pwm.ChangeDutyCycle(duty_cycle)

    def stop(self):
        self.pwm.stop()

class MotorShield:
    def __init__(self):
        self.shift_register = sr.ShiftRegister(data_pin=10, clock_pin=9, latch_pin=11)
        self.motors = []

    def add_motor(self, motor_id, pwm_pin, direction_bits):
        self.motors.append(Motor(pwm_pin, direction_bits))

    def start(self):
        for motor in self.motors:
            motor.pwm.start(0)

    def stop_all_motors(self):
        for motor in self.motors:
            motor.stop()

    def change_duty_cycle(self, motor_id, duty_cycle):
        if motor_id >= len(self.motors):
            raise IndexError("Invalid motor ID")
        self.motors[motor_id].set_duty_cycle(duty_cycle)

    def set_motor_direction(self, motor_id, direction):
        if motor_id >= len(self.motors):
            raise IndexError("Invalid motor ID")
        self.motors[motor_id].set_direction(direction)

class MotorControl(threading.Thread):
