        self.motor_shield.add_motor(2, 12, 0b00001000)  # Motor 2 CCW

        self.motor_shield.start()
        self.motor_shield.change_duty_cycle(1, 75)
        self.motor_shield.change_duty_cycle(2, 50)

        try:
            time.sleep(5)
            self.motor_shield.change_duty_cycle(1, 25)
            time.sleep(5)
        except Exception as e:
            logging.error(f"Error changing duty cycle: {e}")

        self.motor_shield.stop_all_motors()

    def stop(self):
        self.running = False

def on_signal(signum, frame):
    logging.info("Received SIGINT or SIGTERM, stopping motors and cleaning up GPIO resources.")
    motor_control.stop()

if __name__ == "__main__":
