import logging

class MotorError(Exception):
    pass

class Motor:
    def __init__(self, driver, pin):
        if not isinstance(driver, PWM):
            raise MotorError("Invalid driver library.pi instance.")
        self.driver = driver
        self.pin = pin
        self.driver.pin_mode = self.pin
        self.driver.frequency = 1000
        self.driver.duty_cycle = 0

    def set_frequency(self, freq):
        if not 1 <= freq <= 1000:
            raise MotorError("Frequency must be between 1 and 1000 Hz.")
        try:
            self.driver.frequency = freq
        except Exception as e:
            raise MotorError(f"Failed to set frequency: {e}") from e

    def set_duty_cycle(self, duty):
        if not 0 <= duty <= 255:
            raise MotorError("Duty cycle must be between 0 and 255.")
        try:
            self.driver.duty_cycle = duty
        except Exception as e:
            raise MotorError(f"Failed to set duty cycle: {e}") from e

    def stop(self):
        self.set_duty_cycle(0)

    def __del__(self):
        self.stop()

    def close(self):
        self.driver.close()

