import time
import sys
from gpiozero import Servo
from adafruit_circuitpython_modbus import ModbusRTU
from paho.mqtt import client as mqtt_client

class ServoModbusController:
    def __init__(self, port='/dev/serial0', baudrate=115200, register_map):
        self.port = port
        self.baudrate = baudrate
        self.register_map = register_map
        self.modbus = None
        self.servo = Servo(2)  # Assuming servo is connected to GPIO2

        # Setup logging
        logging.basicConfig(level=logging.WARNING)

        # Attempt to open serial port
        try:
            self.ser = serial.Serial(self.port, self.baudrate, timeout=1)
        except (serial.SerialException, OSError):
            logging.warning(f"Unable to open serial port {self.port}.")
            self.ser = None

        if self.ser:
            self.modbus = ModbusRTU(self.ser)
            if not self.modbus.is_connected():
                logging.warning("Modbus RTU device not responding.")
                self.modbus = None

    def read_holding_registers(self, start_register, num_registers):
        if self.modbus and self.modbus.is_connected():
            try:
                result = self.modbus.read_holding_registers(start_register, num_registers, unit=1)
                return result
            except (Exception, TimeoutError) as e:
                logging.warning(f"Error reading holding registers: {e}")
                return None
        return None

    def write_single_holding_register(self, register, value):
        if self.modbus and self.modbus.is_connected():
            try:
                self.modbus.write_single_register(register, value, unit=1)
            except (Exception, TimeoutError) as e:
                logging.warning(f"Error writing single holding register: {e}")

    def write_multiple_holding_registers(self, register, values):
        if self.modbus and self.modbus.is_connected():
            try:
                self.modbus.write_registers(register, values, unit=1)
            except (Exception, TimeoutError) as e:
                logging.warning(f"Error writing multiple holding registers: {e}")

    def move_servo(self, angle):
        self.servo.value = angle

    def cleanup(self):
        if self.modbus:
            self.modbus.close()
        if self.ser:
            self.ser.close()

