import time
import logging
from gpiozero import OutputDevice
from adafruit_pimoroni.automation_hat import AutomationHAT
import board

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class GarageDoor:
    def __init__(self):
        try:
            self.automation_hat = AutomationHAT()
            self.state_pin = 1
            self.relay = OutputDevice(board.D4)  # relay.one

            if not self.automation_hat.is_connected():
                logging.error("Automation HAT not connected. Exiting.")
                exit(0)

            self.automation_hat.input_channel[self.state_pin].switch_to(board.D26)  # GPIO26

            logging.info("GarageDoor initialized.")

        except Exception as e:
            logging.error(f"Error during initialization: {e}")
            exit(1)

    def read_state(self):
        try:
            state = self.automation_hat.input_channel[self.state_pin].value
            if state is None:
                raise ValueError("Unexpected None value from reed switch.")
            return state == board.HIGH

        except Exception as e:
            logging.error(f"Error reading reed switch state: {e}")
            return None

    def control_door(self, state):
        try:
            if state:
                logging.info("Door is closed. Opening the door.")
                self.relay.on()
                time.sleep(0.5)
                self.relay.off()
                logging.info("Door opened. Waiting for door to close.")
            else:
                logging.info("Door is open. Closing the door.")
                self.relay.on()
                time.sleep(0.5)
                self.relay.off()
                logging.info("Door closed.")

        except Exception as e:
            logging.error(f"Error controlling door: {e}")

    def run(self):
        try:
            while True:
                state = self.read_state()
                if state is not None:
                    self.control_door(state)
                time.sleep(1)

        except KeyboardInterrupt:
            logging.info("GarageDoor shutdown initiated. Performing clean shutdown...")
            self.relay.off()
            time.sleep(1)

        except Exception as e:
            logging.error(f"Unexpected error: {e}")
            self.relay.off()

if __name__ == "__main__":
    My_Garage = GarageDoor()
    My_Garage.run()

