import serial
import time
import logging
import sys
import signal
from gpiozero import Servo
from modbus_serial_asyncio import ModbusSerialClient

logging.basicConfig(level=logging.INFO)

class ModbusServoControl:
    def __init__(self):
        self.servo = Servo(17)  # Assuming servo is connected to GPIO17
        self.serial_port = None
        try:
            self.serial_port = serial.Serial('/dev/serial0', 115200, timeout=1)
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port: {e}")
            sys.exit(1)

    def close(self):
        if self.serial_port:
            self.serial_port.close()
            self.serial_port = None

    def move_servo(self, angle):
        if not (0 <= angle <= 180):
            raise ValueError("Angle must be between 0 and 180 degrees")
        try:
            self.serial_port.write(f"AT+SERVOANGLE={angle}\r\n".encode())
            response = self.serial_port.readline().decode().strip()
            if "ERROR" in response:
                raise Exception(response)
        except Exception as e:
            logging.error(f"Failed to move servo: {e}")
            return -1
        return 0

    def read_feedback(self):
        try:
            response = self.serial_port.readline().decode().strip()
            if "ERROR" in response:
                raise Exception(response)
            return float(response)
        except Exception as e:
            logging.error(f"Failed to read feedback: {e}")
            return -1

def signal_handler(signal, frame):
    logging.info("Signal received, shutting down...")
    if modbus_servo_control:
        modbus_servo_control.close()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

if __name__ == "__main__":
    modbus_servo_control = ModbusServoControl()

    try:
        # Start communication
        modbus_client = ModbusSerialClient(method='rtu', port='/dev/serial0', baudrate=115200, timeout=1)
        modbus_client.connect()

        # Move servo to 90 degrees
        error = modbus_servo_control.move_servo(90)
        if error != 0:
            logging.error("Failed to move servo")
            sys.exit(1)

        # Read back feedback
        feedback = modbus_servo_control.read_feedback()
        if feedback < 0:
            logging.error("Failed to read feedback")
            sys.exit(1)
        print(f"Current angle: {feedback} degrees")

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        modbus_servo_control.close()

