import time
import board
import adafruit_pca9685
from adafruit_pca9685 import PWMChannel
import sys

def grab_object(kit):
    try:
        channel = kit.channel_objects[0]
        channel.angle = 90
    except (OSError, ValueError) as e:
        print(f"Error: {e}")

def release_object(kit):
    try:
        channel = kit.channel_objects[0]
        channel.angle = 150
    except (OSError, ValueError) as e:
        print(f"Error: {e}")

def move_servo(kit, target_angle):
    try:
        channel = kit.channel_objects[0]
        current_angle = channel.angle
        if not (0 <= target_angle <= 180):
            raise ValueError("Target angle must be between 0 and 180 degrees.")

        while abs(target_angle - current_angle) > 5:
            current_angle += (target_angle - current_angle) // abs(target_angle - current_angle) * 5
            channel.angle = current_angle
            time.sleep(0.04)
    except (OSError, ValueError) as e:
        print(f"Error: {e}")

def main():
    try:
        i2c = board.I2C()
        kit = adafruit_pca9685.PCA9685(i2c)
        kit.frequency = 50  # Set PWM frequency to 50 Hz

        # Initialize the servo channels
        for channel_num in range(16):
            kit.channels[channel_num].frequency = kit.frequency
            kit.channels[channel_num].pwm = PWMChannel(kit.channels[channel_num])

        grab_object(kit)
        move_servo(kit, 130)  # Move to an intermediate angle
        release_object(kit)

    except KeyboardInterrupt:
        print("\nProgram stopped by user")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        try:
            kit.channels[0].pwm.deactivate()
            kit.close()
        except OSError:
            pass
        sys.exit(0)

if __name__ == "__main__":
    main()

