import argparse
import json
import logging
import time
import board
import adafruit_rfm69
import adafruit_bus_device.i2c_device as i2c_device
import datetime
import adafruit_ds3231

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def load_config(file_path):
    try:
        with open(file_path, 'r') as f:
            config = json.load(f)
        return config
    except FileNotFoundError:
        logging.error("Configuration file not found.")
        exit(1)
    except json.JSONDecodeError:
        logging.error("Invalid JSON in configuration file.")
        exit(1)

def get_rtc_time():
    try:
        i2c = i2c_device.I2C()
        rfm69 = adafruit_rfm69.RFM69(i2c)
        ds3231 = adafruit_ds3231.DS3231(i2c)
        time_data = ds3231.fetch()
        seconds, minutes, hours = time_data.timetuple()[0:3]
        return datetime.time(hours, minutes, seconds)
    except Exception as e:
        logging.error(f"Error reading RTC: {e}")
        return None

def bcd_to_decimal(bcd):
    return (bcd // 100) * 10 + (bcd % 100) // 10 + (bcd % 10)

def transmit_rf(code, repeat):
    try:
        rfm69 = adafruit_rfm69.RFM69(board.D1, mode=adafruit_rfm69.RFM69_433MHZ)
        for _ in range(repeat):
            pulse_duration = 1  # ms
            gap_duration = 10  # ms
            for bit in format(code, '08b'):
                if bit == '1':
                    rfm69.write8(board.D0)
                    time.sleep(pulse_duration / 1000)
                else:
                    time.sleep(pulse_duration / 1000)
                time.sleep(gap_duration / 1000)
    except Exception as e:
        logging.error(f"Error transmitting RF: {e}")

def main(zone, action):
    config = load_config('irrigation_config.json')
    gpio_pin = config.get('gpio_pin', 17)
    transmission_repeat = config.get('transmission_repeat', 3)

    current_time = get_rtc_time() or datetime.datetime.now().time()

    if zone not in ['zone1', 'zone2']:
        logging.error("Invalid zone specified.")
        return

    code = config[f'{zone}_code']
    transmit_rf(code, transmission_repeat)

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="RF Irrigation Controller")
    parser.add_argument("zone", choices=['zone1', 'zone2'], help="Zone to control (zone1 or zone2)")
    parser.add_argument("action", choices=['on', 'off'], help="Action to perform (on or off)")
