import serial
import time
import threading
import atexit
import paho.mqtt.client as mqtt

class ESP8266Control:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.ser = None
        self.try_count = 0
        self._open_uart()

    def _open_uart(self):
        try:
            self.ser = serial.Serial(self.port, self.baud_rate, timeout=self.timeout)
        except serial.SerialException:
            print(f"Failed to open UART port {self.port}")
            self.ser = None

    def _send_command(self, command, timeout=None):
        if timeout is None:
            timeout = self.timeout
        try:
            self.ser.write((command + b'\r\n').encode())
            response = b''
            while self.ser.in_waiting > 0:
                line = self.ser.readline().decode().strip()
                if line.endswith('OK') or line.endswith('ERROR') or line.endswith('FAIL'):
                    return line
                response += line
                if 'ready' in line.lower():
                    break
            if timeout < time.time() - self.try_count:
                return None
            return response
        except Exception as e:
            print(f"Error sending command: {e}")
            return None

    def test_connection(self):
        return self._send_command('AT') == b'OK'

    def restart(self):
        self._send_command('AT+RST')
        time.sleep(2)
        return self.test_connection()

    def connect_wifi(self, ssid, password):
        self._send_command('AT+CWJAP', timeout=10)
        self._send_command('AT+CWJAP?')
        if b'join failed' in self._send_command('AT+CWJAP?'):
            raise Exception("Failed to connect to WiFi")

    def disconnect_wifi(self):
        self._send_command('AT+CWQAP')

    def get_ip(self):
        response = self._send_command('AT+CIFSR')
        if response is not None:
            return response.split(b':')[1]
        return None

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        self._send_command('AT+CIPSTART="TCP",{},{},{}'.format(host, port, url).encode())
        self._send_command('AT+CIPSEND={}'.format(len(data) if data else 0).encode())
        if data:
            self.ser.write(data)
        response = b''
        while b'+IPD,':
            packet = self.ser.read_until(b'\r\n')
            response += packet
            if b'CLOSED' in packet:
                break
        return response

    def receive_http_response(self, timeout=5.0):
        start_time = time.time()
        while time.time() - start_time < timeout:
            line = self.ser.readline().decode().strip()
            if line.startswith('+IPD,'):
                payload_length = int(line[4:].split(':')[0])
                payload = self.ser.read(payload_length)
                return payload
        return None

    def __del__(self):
        if self.ser:
            self.ser.close()

if __name__ == "__main__":
    esp = ESP8266Control()

    # Test connection
    if esp.test_connection():
        print("ESP8266 connected successfully")
    else:
        print("ESP8266 not responding, attempting restart...")
        if esp.restart():
            print("Restart successful, trying to connect again...")
        else:
            print("Restart failed, exiting.")
            exit(1)

    # Connect to WiFi
    esp.connect_wifi('your_SSID', 'your_PASSWORD')

    # Get IP address
    ip = esp.get_ip()
    print(f"ESP8266 IP: {ip}")

    # Send HTTP request
    response = esp.send_http_request('GET', '/', 'example.com', 80)
    print("HTTP Response:", response)

    # Receive HTTP response
    received_data = esp.receive_http_response()
    print("Received Data:", received_data)

    # Clean up and exit
    atexit.register(esp.__del__)

