from gpiozero import LED
from time import sleep

logging.basicConfig(level=logging.INFO)
log = logging.getLogger(__name__)

class SimpleGPS:
    def __init__(self):
        self._serial = None
        self._led = LED(17)  # Assuming LED is connected to GPIO17
        self._led.off()

    def connect(self):
        try:
            self._serial = serial.Serial('/dev/serial0', 9600, timeout=1)
            self._led.on()
            return True
        except OSError:
            log.error("Failed to connect to GPS device.")
            self._led.off()
            return False

    def read_data(self):
        if self._serial is None or not self._serial.is_open:
            return None
        try:
            data = self._serial.readline().decode('utf-8').strip()
            return data
        except (ValueError, UnicodeDecodeError):
            self._led.off()
            return None

    def parse_gga(self, line):
        if not line.startswith('$GPGGA') and not line.startswith('$GNGGA'):
            return None
        try:
            parts = line[1:].split(',')
            utc_time = parts[1]
            latitude = parts[3]
            longitude = parts[5]
            fix_quality = parts[6]
            num_satellites = parts[7]
            return {
                'utc_time': utc_time,
                'latitude': latitude,
                'longitude': longitude,
                'fix_quality': fix_quality,
                'num_satellites': num_satellites
            }
        except (IndexError, ValueError):
            log.error(f"Malformed GPS data: {line}")
            return None

    def close(self):
        if self._serial is not None and self._serial.is_open:
            try:
                self._serial.close()
                self._led.off()
            except Exception as e:
                log.error(f"Error closing GPS serial port: {e}")

def main():
    gps = SimpleGPS()
    if gps.connect():
        log.info("GPS connected.")
        while True:
            data = gps.read_data()
            if data and data.startswith('$GPGGA') or data.startswith('$GNGGA'):
                parsed_data = gps.parse_gga(data)
                if parsed_data:
                    log.info(f"Parsed GPS data: {parsed_data}")
            try:
                sleep(0.2)
            except KeyboardInterrupt:
                gps.close()
                log.info("Clean shutdown initiated.")
                break

if __name__ == "__main__":
    main()

