            return False
    return True

def close_uart():
    global uart_port
    with uart_lock:
        if uart_port:
            uart_port.close()
            uart_port = None

def send_command_and_read_response(command: str) -> str:
    with uart_lock:
        if not uart_port:
            return ""

        uart_port.write(command.encode())
        uart_port.flushInput()
        response = ""
        try:
            response = uart_port.read(uart_port.inWaiting()).decode().strip()
        except Exception as e:
            print(f"Error reading from UART port: {e}")
        return response

def handle_sigint_sigterm(signal, frame):
    print("\nReceived SIGINT or SIGTERM, closing UART port and stopping the web service...")
    close_uart()
    exit(0)

