import serial
import time
import re

class PulseOximeterReader:
    def __init__(self, port='/dev/ttyUSB0', baudrate=9600):
        self.port = port
        self.baudrate = baudrate
        self.ser = None
        self.pattern = re.compile(r'^(\d+),(\d+(\.\d+)?)$')

    def setup(self):
        try:
            self.ser = serial.Serial(self.port, self.baudrate, timeout=1)
        except serial.SerialException as e:
            print(f"Error opening serial port: {e}")
            raise

    def read_data(self):
        if not self.ser.is_open:
            self.setup()

        try:
            while True:
                data = self.ser.readline().decode('ascii', errors='replace').strip()
                if not data:
                    continue

                match = self.pattern.match(data)
                if not match:
                    raise ValueError(f"Invalid data format: {data}")

                heart_rate, spo2 = map(float, match.groups())
                print(f"Heart Rate: {int(heart_rate)} bpm, SpO2: {spo2 * 100:.1f}%")
                time.sleep(1)

        except ValueError as e:
            print(f"Warning: {e}")
        except KeyboardInterrupt:
            print("\nExiting...")
        except Exception as e:
            print(f"An unexpected error occurred: {e}")
        finally:
            if self.ser.is_open:
                self.ser.close()

if __name__ == "__main__":
    reader = PulseOximeterReader()
    reader.read_data()

