    try:
        item = next((i for i in app.config['data'] if i['id'] == item_id), None)
        if item:
            return jsonify(item)
        else:
            abort(404)
    except IndexError:
        abort(404)

@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
