        data = request.get_json(force=True) or request.form
        new_item = {'id': len(app.config['data']) + 1, 'name': data.get('name', ''), 'done': data.get('done', False).lower() in ['true', 'false', 'True', 'False']}
        app.config['data'].append(new_item)
        return jsonify(new_item), 201
    except Exception as e:
        return jsonify({'error': str(e)}), 400

def init_serial():
    global ser
    ser = serial.Serial('/dev/ttyUSB0', 9600, timeout=0)

def init_lcd():
    global lcd
    lcd = LCD(rs=27, e=22, d4=25, d5=17, d6=18, d7=23, cols=20, rows=4)
    lcd.clear()
    lcd.message('\n'.join(str(i) for i in app.config['data']))

def close_serial():
    global ser
    if ser:
        ser.close()

@app.teardown_appcontext
def shutdown_serial(exception):
    close_serial()

if __name__ == '__main__':
