import time
import serial
import sys
import threading

def send_command(ser, command):
    ser.write((f'X{command}\n').encode())

def read_input():
    while True:
        try:
            user_input = input()
            if user_input.lower() == "exit":
                break
            yield user_input
        except KeyboardInterrupt:
            print("Exitting...")
            break

def main():
    try:
        ser = serial.Serial(
            port='/dev/rfcomm4',
            baudrate=38400,
            timeout=1
        )
        if not ser.is_open:
            raise RuntimeError("Failed to open serial port /dev/rfcomm4")

        input_generator = read_input()
        try:
            while True:
                command = next(input_generator)
                send_command(ser, command)
                time.sleep(0.1)
        except RuntimeError as e:
            print(e)
        finally:
            ser.close()

    except RuntimeError as e:
        print(e)
        sys.exit(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

